// mcp.schema.json
/** Configured state plus observed state. Negotiated version and capabilities are observations, not copied claims. */
export type MCPServer = {
  id: ID;
  revision: Revision;
  source: {
    kind: "user";
  };
  name: string;
  transport: "http" | "stdio";
  endpoint?: string;
  connection_id?: ID;
  enabled: boolean;
  exposure?: {
    default?: "direct" | "discoverable" | "disabled";
    overrides?: Record<string, "direct" | "discoverable" | "programmatic" | "disabled">;
  };
  observed: {
    status: "disconnected" | "connecting" | "connected" | "needs_sign_in" | "failed" | "disabled";
    protocol_version?: string;
    capabilities?: string[];
    discovery_revision?: string;
    tool_count?: number;
    resource_count?: number;
    prompt_count?: number;
    last_success_at?: Instant;
    error?: ErrorDetail;
    /** Redacted */
    diagnostics?: ({
      at: Instant;
      level: "info" | "warning" | "error";
      message: string;
    })[];
    /** Whether a configured credential is stored; never its value */
    credential?: "missing" | "present";
  };
  auth?: "none" | "oauth" | "configured";
};
export type MCPServerEditable = {
  name: string;
  endpoint?: string;
  /** Reference to a declared managed command, not a literal command line */
  command_ref?: string;
  /** Names of secret or configuration references, never literal values */
  environment_refs?: string[];
  auth: "none" | "oauth" | "configured";
  enabled: boolean;
  exposure: {
    default?: "direct" | "discoverable" | "disabled";
    overrides?: Record<string, "direct" | "discoverable" | "programmatic" | "disabled">;
  };
} & ({
  transport: "http";
} | {
  transport: "stdio";
});
export type MCPServerChange = {
  request_id: UUID;
  /** 0 for create; current revision otherwise */
  expected_revision: Revision;
  value: MCPServerEditable;
};
export type MCPServerAction = {
  request_id: UUID;
  expected_revision: Revision;
  value: ({
    action: "connect" | "reconnect" | "sign_in" | "sign_out" | "start" | "stop" | "restart";
  } | {
    action: "set_exposure";
    tool: string;
    exposure: "direct" | "discoverable" | "programmatic" | "disabled";
  });
};
export type MCPServerTool = {
  name: string;
  title: string;
  exposure: "direct" | "discoverable" | "programmatic" | "disabled";
  definition: DefinitionRef;
  availability: "ready" | "needs_connection" | "needs_permission" | "disabled" | "unavailable";
};
/** POST /v1/mcp/{id}/credential (r2.3). Write-only; the receipt's resource is the MCPServer and never echoes the token. Custody stays behind D1. */
export type MCPCredentialInput = {
  request_id: UUID;
  token: string;
};

// permissions.schema.json
/** Every selector is an explicit allowlist; an empty list matches nothing. Wildcards are explicit values, never implied by absence. */
export type PermissionRule = {
  id: ID;
  revision: Revision;
  effect: "allow" | "ask" | "deny";
  tool_ids: string[];
  connection_ids: ID[];
  resource_ids: string[];
  action_classes: Effect[];
  /** Omitted authorizes nobody for recipient-addressed actions; the explicit wildcard is the string "*" */
  recipients?: string[];
  automation_id?: ID;
  expires_at?: Instant;
  max_operations?: number;
  title?: string;
  created_at?: Instant;
  updated_at?: Instant;
  goal_id?: ID;
  /** Server-rendered readable summary of the exact selectors */
  summary?: string;
};
export type PermissionRuleEditable = {
  effect: "allow" | "ask" | "deny";
  tool_ids: string[];
  connection_ids: ID[];
  resource_ids: string[];
  action_classes: Effect[];
  recipients?: string[];
  automation_id?: ID;
  expires_at?: Instant;
  max_operations?: number;
  title?: string;
  goal_id?: ID;
};
export type PermissionRuleChange = {
  request_id: UUID;
  /** 0 for create; current revision otherwise */
  expected_revision: Revision;
  value: PermissionRuleEditable;
};
export type PermissionDecision = {
  result: "allow" | "deny" | "needs_interaction";
  reason: string;
  interaction_id?: ID;
};
export type QuestionPayload = {
  input: "text" | "choice" | "multi_choice" | "date" | "confirm";
  options?: {
    id: string;
    label: string;
  }[];
  constraints?: {
    max_length?: number;
    pattern?: string;
  };
};
/** The digest lives only on Interaction.action_digest (F10). */
export type ApprovalPayload = {
  summary: string;
  tool_id?: string;
  warning?: string;
  effect: Effect;
  account: {
    connection_id: ID;
    label: string;
  };
  resources: ResourceRef[];
  recipients?: string[];
  /** Readable consequences, e.g. attendees will be notified */
  material_effects?: string[];
  card?: CardPart;
};
export type AccountSelectionPayload = {
  purpose: string;
  eligible_connection_ids: ID[];
  remember_as_default?: boolean;
};
/** Server-created sign-in request. For OAuth it carries the authorize URL and expiry; for an app-password integration only where to enter the pair. Never credentials. For an MCP server, integration_id is "mcp" and connection_id is the server id. */
export type SignInPayload = {
  auth_attempt_id?: ID;
  integration_id: string;
  /** The connection, or the MCP server id when integration_id is mcp */
  connection_id?: string;
  authorize_url?: string;
  requested_scopes?: string[];
  return_to?: string;
  expires_at?: Instant;
} & ({
  auth: "oauth";
} | {
  auth: "app_password";
});
/** A task correction supersedes a pending interaction (status superseded, revision+1, superseded_by) in the same transaction that advances the instruction revision, so a response at the old expected_revision is a 409 (I6). */
export type Interaction = {
  id: ID;
  revision: Revision;
  task_id?: string;
  instruction_revision?: number;
  conversation_id?: string;
  automation_id?: ID;
  status: "pending" | "resolved" | "expired" | "superseded";
  prompt: string;
  payload: JSON;
  action_digest?: string;
  expires_at?: Instant;
  created_at?: Instant;
  resolved_at?: Instant;
  /** Set when this interaction projects an existing state.Question */
  legacy_question_id?: string;
  superseded_by?: ID;
  task_title?: string;
  resolution?: {
    kind: "answer" | "approve" | "decline" | "choose_account" | "signed_in" | "expired";
    text?: string;
    connection_id?: ID;
    at: Instant;
  };
} & ({
  kind: "question";
  payload: QuestionPayload;
} | {
  kind: "approval";
  payload: ApprovalPayload;
} | {
  kind: "account_selection";
  payload: AccountSelectionPayload;
} | {
  kind: "sign_in";
  payload: SignInPayload;
});
export type InteractionResponse = {
  request_id: UUID;
  /** 0 for create; current revision otherwise */
  expected_revision: Revision;
  value: ({
    kind: "answer";
    text: string;
    option_ids?: string[];
  } | {
    kind: "approve" | "decline";
    action_digest: string;
    remember_rule?: boolean;
  } | {
    kind: "choose_account";
    connection_id: ID;
    remember_as_default?: boolean;
  } | {
    kind: "decline";
  });
};

// tools.schema.json
export type Binding = {
  adapter: "native" | "mcp";
  target: string;
  version: string;
};
export type Policy = {
  effect: Effect;
  retry: "safe" | "provider_key" | "reconcile_only";
  timeout_ms: number;
  /** Where the call runs */
  location: "runtime";
  interrupted_cost_usd?: number;
  interrupted_cost_unknown?: boolean;
  cancellation?: "cooperative" | "none";
};
export type ToolDefinition = {
  ref: DefinitionRef;
  extension: DefinitionRef;
  /** Model-facing alias (B1: OpenAI rejects '.'). External tools namespace with '__' (gcal__events_list, mcp_<server>__<tool>) plus a short stable hash when over 64. Unique across the effective tool set; built-ins win; collisions are rejected at install (B10). */
  model_name: string;
  title: string;
  description: string;
  /** Canonical JSON Schema 2020-12 as supplied by the provider */
  input_schema: Record<string, unknown>;
  output_schema?: Record<string, unknown>;
  /** Recorded version of the model-facing schema projection, when one was applied */
  model_schema_transform?: string;
  binding: Binding;
  connection_type?: string;
  policy: Policy;
  exposure: "direct" | "discoverable" | "programmatic" | "disabled";
};
export type AvailableTool = {
  tool: DefinitionRef;
  title: string;
  description: string;
  connection_ids: ID[];
  availability: "ready" | "needs_connection" | "needs_permission" | "disabled" | "unavailable";
  reason_code?: string;
  recovery?: "connect" | "repair" | "enable" | "choose_account" | "request_access";
  /** Stable capability id, e.g. calendar, web_search (B9) */
  capability: string;
  integration_id?: string;
  effect?: Effect;
  exposure?: "direct" | "discoverable" | "programmatic" | "disabled";
};
export type AvailableToolList = {
  items: AvailableTool[];
  next_cursor?: string;
};

export type AssistantFeature = keyof AssistantCapabilities["assistant_features"];
